package cl.acis.ordenes.service; import cl.acis.ordenes.exception.*; import cl.acis.ordenes.model.*; import org.springframework.stereotype.Component; import java.util.*;
@Component public class ReglasOrden { public Set<AccionOrden> disponibles(OrdenTrabajo o,String rol,Long actor){Set<AccionOrden>s=EnumSet.noneOf(AccionOrden.class);boolean admin=rol.equals("ADMINISTRADOR"),jef=admin||rol.equals("JEFATURA"); if(o.getEstado()==EstadoOrden.CREADA&&jef)s.add(AccionOrden.ASIGNAR); if(o.getEstado()==EstadoOrden.ASIGNADA&&rol.equals("TECNICO")&&actor.equals(o.getTecnicoId())){s.add(AccionOrden.ACEPTAR);s.add(AccionOrden.RECHAZAR);}if(o.getEstado()==EstadoOrden.ACEPTADA&&rol.equals("TECNICO")&&actor.equals(o.getTecnicoId()))s.add(AccionOrden.CHECK_IN);if(o.getEstado()==EstadoOrden.EN_EJECUCION&&rol.equals("TECNICO")&&actor.equals(o.getTecnicoId()))s.add(AccionOrden.CHECK_OUT);if(o.getEstado()==EstadoOrden.CERRADA&&(jef||(rol.equals("CLIENTE")&&actor.equals(o.getClienteId())))){s.add(AccionOrden.VALIDAR);s.add(AccionOrden.OBSERVAR);}if(o.getEstado()==EstadoOrden.OBSERVADA&&jef)s.add(AccionOrden.REABRIR);if(jef&&!o.getEstado().equals(EstadoOrden.VALIDADA)&&!o.getEstado().equals(EstadoOrden.CANCELADA)){s.add(AccionOrden.REPROGRAMAR);if(o.getEstado()!=EstadoOrden.CERRADA)s.add(AccionOrden.CANCELAR);}return s;}
 public void exigir(OrdenTrabajo o,AccionOrden a,String rol,Long actor){if(!disponibles(o,rol,actor).contains(a))throw new ReglaNegocioException("La acción no está permitida para el estado y rol actuales");}
}
